import{_ as t,c as o,o as e,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易尚氏学 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易尚氏学 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/007.md","filePath":"zh/classics/shangshi/007.md"}'),h={name:"zh/classics/shangshi/007.md"};function p(u,a,i,q,l,n){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>元亨。谓二五也。乾元亨二五独吉。坤亦然。元亨并无阴阳之分。虞仲翔谓坤含光大。凝乾之元。终于坤亥。出乾初子。故元亨。案彖传曰。至哉坤元。是坤亦言元。不专属乾。坤六五云。黄裳元吉。是其证。乾为马。坤为牝。贞卜问也。利牝马之贞。即利牝马之占也。牝马柔顺。言阴必顺阳也。君子有攸往。言具坤德之君子。有所行也。惠栋端木国湖泥于坤为小人之象。谓君子指阳非也。地道无成。故不可先。先则迷而失道。惟随阳之后。以阳为主。则靡不利也。西南得朋。东北丧朋。旧解以朋字类字失诂。故鲜得解者。马融荀爽以阴遇阴为朋。虞翻谓失之甚矣。乃用参同契。月三日出庚。震象。八日见丁方。兑象。兑二阳为朋。庚西丁南。故曰西南得朋。三十日坤象。月灭乙癸。癸北乙东。故曰东北丧朋。苦心搜索以求朋象。岂知兑之为朋。以阴遇阳。非以二阳。阳遇阳同人谓之敌刚。阴遇阴中孚谓之得敌。然则虞说与马荀背易理等耳。然支离穿凿。则过于马荀矣。复曰朋来无咎。蹇九五曰。大蹇朋来。解九四曰朋至斯孚。皆以阴得阳为朋。而坤逆行。消息卦自西而南阳日增。自东而北阳递减。增则得朋。减则丧朋。而坤道无成。故安静贞定则吉也。</p><p>彖曰。至哉坤元。万物资生。乃顺承天。坤厚载物。德合无疆。含弘光大。品物咸亨。牝马地类。行地无疆。柔顺利贞。君子攸行。先迷失道。后顺得常。西南得朋。乃与类行。东北丧朋。乃终有庆。安贞之吉。应地无疆。</p><p>何休公羊传元年注云。元者气也。万物资坤元以生。坤元实顺天以行。故天道广大无疆。惟坤之德能合之也。万物皆孕毓于地。故曰含弘。万物皆成长于地。故曰光大。光大则咸亨矣。</p><p>阴阳合为类。乾为马。故马与地类。而牝马尤与地类。君子攸行者。谓柔顺利贞之德。为君子所法也。九家谓乾来据坤。为君子攸行。失传旨。</p><p>夫曰行曰终。乃自西而南。自东而北而逆行也。非以西南东北相对待也。明矣。消息卦自西而南阳日增。故曰西南得朋。阴以阳为类。故曰乃与类行。消息卦自东而北阳递减。故曰东北丧朋。夫事有终必有始。丧朋之地始于巳。终于亥。坤行至亥。阳丧尽而为纯坤。乃反曰有庆者何也。则以周易之位。乾原居亥。纯坤与纯乾相遇。天地合德。万物由此出生。故曰有庆。易凡言有庆者。皆谓阴遇阳。大畜晋睽六五。皆上承阳。故皆曰往有庆。易林中孚之坤云。符左契右。相与合齿。乾坤利贞。乳生六子。太玄玄文云。入冥出冥。新故代更。皆说有庆之故也。后儒皆承用虞氏解。谓坤行至西南。月又将生明为有庆。是不知终为何处也。终者艮象亥方。周礼宰夫。及大司徒岁终注。皆日周季冬也。周季冬为亥月。又尔雅释天云。月在壬曰终。壬亦亥方。是终指亥方甚明。说卦云。艮成终。终于亥也。故夫洞明易理者。莫过于焦延寿与杨子云也。(焦氏易诂。有详说。可参阅。)</p><p>坤道主静。故曰安。易林云。乾坤利贞。乳生六子。安贞即利贞。利贞即天地合德。合则相感。故曰应地无疆。</p><p>象日。地势坤。君子以厚德载物。</p><p>王弼曰。地形不顺其势顺。是王弼之本。作地势顺也。来衷曰。地有上下九等之差。故以形势言其性。夫曰性则亦读为顺也。而皆未引说卦坤顺为诂。是愈证宋王本之皆作地势顺。故不引说卦为证。盖坤古文作&quot;巛&quot;。而&quot;巛&quot;为顺之叚字。故宋王皆读&quot;巛&quot;为顺。自正义改作坤。而顺字遂无由识。至清儒王引之等。据说卦乾健坤顺之文。谓天行健。即天行乾。地势顺即地势坤。夫乾坤之为天地。不惟说卦言之。彖象传并言之。故以天代乾。以地代坤。今不从宋王注。以坤为顺之讹字。(若作&quot;巛&quot;则不讹)谓天行健即天行乾。地势顺即地势坤。是天行天地势地也。尚可通乎。王又谓&quot;巛&quot;即川字。川与坤顺声近。故借川作坤。是尤不安。夫坤古作&quot;巛&quot;。是古文作&quot;巛&quot;也。隶书原以变古文之繁重。若&quot;巛&quot;字本即简易。故隶书常因而不改。大戴礼保傅篇。易之乾&quot;巛&quot;。家语执辔篇。此乾&quot;巛&quot;之美。后汉舆服志。尧舜垂裳。盖取诸乾&quot;巛&quot;。北史太和三年。&quot;巛&quot;德六合殿成。又坤字之见于汉碑者。无不作&quot;巛&quot;。再征之金文。周师訇敦铭云。用作&quot;巛&quot;宫宝。王陶庐云。&quot;巛&quot;即坤字。由此证&quot;巛&quot;即坤。非有所借也明矣。引之谓顺因川而得声。愚以为顺因&quot;巛&quot;而得声。推之训驯巡紃等字皆然。引之盖泥于说文坤下无重&quot;巛&quot;之文。谓&quot;巛&quot;非坤本字。王陶庐云。玉篇&quot;巛&quot;下注曰古文坤字。广韵亦曰古文以坤为&quot;巛&quot;。二书皆胚胎于说文。据此说文必有&quot;巛&quot;字。后夺之耳。不然二书不敢臆造。又云释文原云。&quot;巛&quot;本又作坤。坤今字。今改为坤本又作&quot;巛&quot;。&quot;巛&quot;今字。文理谬戾已极。是皆因孔氏改&quot;巛&quot;作坤。后人遂并释文而亦改矣。按王说是也。诗周颂有夷之行。释文云。&quot;巛&quot;苦魂反。字亦作坤。此处释文应同。然则坤本作&quot;巛&quot;。征之金石传记无不然。汉本易之作地势顺。征之宋注王注亦无不然。然今本易何以讹作地势坤。则以汉本易。坤原作&quot;巛&quot;。乃借&quot;巛&quot;为顺也。何言之。顺既因&quot;巛&quot;而得声。在古文例常叚借。如大壮卦以易为场，夬以次且为趑趄。小畜以血为恤。皆因其得声之字而叚借。今以&quot;巛&quot;叚顺。正其例耳。孔氏知&quot;巛&quot;即坤。不知&quot;巛&quot;为顺之叚字。遂竟改作坤矣。若宋王则皆读作顺也。以宋王本皆作&quot;巛&quot;也。作&quot;巛&quot;则人易知为顺矣。其以说卦为解者。于字之沿革。尽失其义。厚德载物者坤。君子取以为法。虞仲翔必谓君子为乾亦非。又易以&quot;巛&quot;为大川。焦氏易林以&quot;巛&quot;为水。为江河淮济。九家注蛊亦以坤地为水。邵子坤水之象之所本也。盖&quot;巛&quot;即川字即水字。故易林复以坎为土。邵子复本之。疑古以水土为一物。能合而不能分。比曰地上有水。师曰地中有水。证以古文。稽之卦象。而益信矣。</p><p>(金文水作氺。两旁画不连。刘涧琴云。效鼎涉作氺。殷契衍作氺。囦作氺。又永字从水。而金文作氺。是皆水字两旁画皆不断。可证&quot;巛&quot;川水三字。古文皆同。)</p><p>初六。履霜。坚冰至。</p><p>阳进阴退。阳顺阴逆。故阳自七进九为老阳。阴自八退六为老阴。阴极则变。故易用六也。于卦为姤。时当夏至。一阴初生。初震爻故曰履。阴微故以霜为喻。乾为冰为坚。坤行至上当亥方。与乾相遇。故曰坚冰。言五月微阴初见。驯至亥月而极寒。必然之势。当憬然悟也。乾宝以五月无霜。谓阴气既动。则必至于履霜。必至于坚冰者非也。霜即喻此微阴。微阴见故曰履霜。非有待于后也。其待者乃坚冰也。</p><h3 id="象日。履霜。阴始凝也。" tabindex="-1">象日。履霜。阴始凝也。 <a class="header-anchor" href="#象日。履霜。阴始凝也。" aria-label="Permalink to “象日。履霜。阴始凝也。”">​</a></h3><p>(依郭京读)驯至其道。至坚冰也。乾为坚冰。言阴生于午。至亥纯坤与纯乾相遇。故曰至。</p><p>六二。直方大。不习无不利。</p><p>二为坤本位。坤二之利。与乾五之利同也。后人泥于乾动为直。及小往大来之文。必以直大属之乾。于是经义遂迂曲而不得解。岂知直方大皆谓坤。彖传文言所释至明。文言云。直其正也。正谓二。二得位中正。故曰直。彖传云。含弘光大。大谓坤。坤万物资生。焉得不大。盖方者地之体。大者地之用。而二又居中直之位。故曰直方大。后儒见象传未言大。便疑大为衍文。然陆德明时。汉魏六朝本具在。从无谓大字衍者。况文言引亦有大字乎。阴消至二遁。前承重阳。得主有利。故不习无不利。文言释曰。不疑其所行。正谓二承阳也。</p><h3 id="象日。六二之动。直以方也。不习无不利。地道光也。" tabindex="-1">象日。六二之动。直以方也。不习无不利。地道光也。 <a class="header-anchor" href="#象日。六二之动。直以方也。不习无不利。地道光也。" aria-label="Permalink to “象日。六二之动。直以方也。不习无不利。地道光也。”">​</a></h3><p>六二与九五相上下。故曰动。阴顺阳。故曰地道光。</p><p>六三。含章可贞。或从王事。无成。有终。</p><p>坤为文。故曰章。坤闭故曰含章。阴消至三否。正君子俭德避难之时。故虽有文章。含而不露。贞静自守。荀虞谓三阳位。以阴据其上。故曰含章。后儒多从之。非也。文言释章为美。仍坤象。非谓阳位也。否上乾为王。三承重阳。故曰从王事。三不当位故或之。与或跃在渊义同。言慎审也。阴顺阳。故无敢成。成法也。式也。言不敢作法也。阴始姤。代乾终事。故曰有终。○按纯坤无乾。王事之象何来乎。须知乾息从复始。坤消从姤始。故复姤亦为小父母。坤消至三。上乾如故也。故曰从王事。彼夫讼三曰从王事。履三曰武人为于大君。皆以上承阳。兹与之同。观初爻曰。履霜坚冰至。言阳将以次消也。故卦虽无乾。爻辞皆视乾而系也。先儒坐不明此理。又鲜能以易解易。故说王事皆无着。</p><h3 id="象日。含章可贞。以时发也。或从王事。知光大也。" tabindex="-1">象日。含章可贞。以时发也。或从王事。知光大也。 <a class="header-anchor" href="#象日。含章可贞。以时发也。或从王事。知光大也。" aria-label="Permalink to “象日。含章可贞。以时发也。或从王事。知光大也。”">​</a></h3><p>时不可。故俟时而发。或从王事。知时至矣。故曰光大。</p><p>六四。括囊。无咎无誉。</p><p>坤为囊。杨子方言。括关闭也。坤闭故曰括囊。阴消至四八月观。天地将闭塞矣。阴在三否。阴阳平均。故或从王事。至四则阴盛阳衰。时不可矣。故括囊。言无所表着也。无与于世。故无咎誉。</p><h3 id="象日。括囊无咎。慎不害也。" tabindex="-1">象日。括囊无咎。慎不害也。 <a class="header-anchor" href="#象日。括囊无咎。慎不害也。" aria-label="Permalink to “象日。括囊无咎。慎不害也。”">​</a></h3><p>慎故无咎。不害即无咎也。</p><p>六五。黄裳元吉。</p><p>坤为裳。色黄。故曰黄裳。坤为下。裳得下饰。五位正中。黄者中色。故曰黄裳元吉。元者善之长。五位极尊。故曰元。元谓五。大有鼎皆曰元吉。皆谓六五。毛奇龄谓五降二承乾为元吉。以元专属乾。非也。</p><h3 id="象曰。黄裳元吉。文在中也。" tabindex="-1">象曰。黄裳元吉。文在中也。 <a class="header-anchor" href="#象曰。黄裳元吉。文在中也。" aria-label="Permalink to “象曰。黄裳元吉。文在中也。”">​</a></h3><p>坤为文。黄裳文饰。言所以吉者。以居中位也。</p><p>上六。龙战于野。其血玄黄。</p><p>阴至上六。坤德全矣。故万物由以出生。然孤阴不能生也。荀爽云。消息之位。坤在于亥。下有伏乾。阴阳相和。故曰龙战于野。坤为野。龙者阳。说文壬下云。易曰龙战于野。战者接也。乾凿度云。乾坤合气戌亥。合气即接。九家云。玄黄天地之杂。言乾坤合居。夫曰相和。曰合气。曰合居。则战之为和合明矣。皆与许诂同也。而万物出生之本由于血。血者天地所遗氤氲之气。天玄地黄。其血玄黄者。言此血为天地所和合。故能生万物也。易林说此云。(中孚之坤)符左契右。相与合齿。乾坤利贞。乳生六子。夫曰符契。曰合齿。则乾坤接也。即龙战于野也。消息卦。坤亥下即震子出。故曰乳生六子。彖传云。乃终有庆。庆此也。惟荀与九家。皆以血为阴。仍违易旨。易明言天地杂。则血非纯阴可知。纯阴则离其类矣。胡能生物。至侯果谓阴盛似阳。王弼乾宝谓阴盛逼阳。阳不堪故战。以战为战争。后孔颖达朱子。因经言战又言血。疑阴阳两伤者。皆梦呓语也。清儒独惠士奇用许说谓战者接也。阴阳交接。卦无伤象。识过前人远矣。</p><h3 id="象日。龙战于野。其道穷也。阴至上六而极。故曰穷。穷尽也。" tabindex="-1">象日。龙战于野。其道穷也。阴至上六而极。故曰穷。穷尽也。 <a class="header-anchor" href="#象日。龙战于野。其道穷也。阴至上六而极。故曰穷。穷尽也。" aria-label="Permalink to “象日。龙战于野。其道穷也。阴至上六而极。故曰穷。穷尽也。”">​</a></h3><p>用六。利永贞。</p><p>此亦明筮例也。八六皆阴。今遇阴。胡以只言六不言八。则以六为用而变七也。利永贞。申用六之故也。六何以必变。六为老阴。阴极不返。则太柔矣。又言曰。贞固足以乾事。永贞则健而阳矣。故象曰以大终。大者阳。言阴极则变阳也。</p><h3 id="象曰。用六永贞。以大终也。" tabindex="-1">象曰。用六永贞。以大终也。 <a class="header-anchor" href="#象曰。用六永贞。以大终也。" aria-label="Permalink to “象曰。用六永贞。以大终也。”">​</a></h3><p>阳大阴小。以大终者。言阴极必返阳也。旧解因不知用六义意。故说大终。无有当者。</p><p>文言</p><h3 id="坤至柔而动也刚。至静而德方。后得主而有常。含万物而化光。坤道其顺乎。承天而时行。" tabindex="-1">坤至柔而动也刚。至静而德方。后得主而有常。含万物而化光。坤道其顺乎。承天而时行。 <a class="header-anchor" href="#坤至柔而动也刚。至静而德方。后得主而有常。含万物而化光。坤道其顺乎。承天而时行。" aria-label="Permalink to “坤至柔而动也刚。至静而德方。后得主而有常。含万物而化光。坤道其顺乎。承天而时行。”">​</a></h3><p>坤柔动刚。义与用六大终同。言坤虽至柔。遇六则变阳矣。故曰动刚。后得主而有常者。言最后变六为阳。以阳为主也。</p><h3 id="积善之家。必有余庆。积不善之家。必有余殃。臣弒其君。子弒其父。非一朝一夕之故。其所由来者渐矣。由辩之不早辩也。易曰。履霜坚冰至。盖言顺也。" tabindex="-1">积善之家。必有余庆。积不善之家。必有余殃。臣弒其君。子弒其父。非一朝一夕之故。其所由来者渐矣。由辩之不早辩也。易曰。履霜坚冰至。盖言顺也。 <a class="header-anchor" href="#积善之家。必有余庆。积不善之家。必有余殃。臣弒其君。子弒其父。非一朝一夕之故。其所由来者渐矣。由辩之不早辩也。易曰。履霜坚冰至。盖言顺也。" aria-label="Permalink to “积善之家。必有余庆。积不善之家。必有余殃。臣弒其君。子弒其父。非一朝一夕之故。其所由来者渐矣。由辩之不早辩也。易曰。履霜坚冰至。盖言顺也。”">​</a></h3><p>坤为积为殃为恶。故曰不善。坤多故曰余。又为臣子为弒为夕。君父则指乾也。坤消阳故曰弒君父。此正申明履霜坚冰至之理。阴在姤至微耳。积之不已。则阳可全消。其祸有不可胜言者。故曰余殃。余者多也，此本世界之公理。人事之自然。而李鼎祚忽以夫子不语怪力乱神为疑。若余庆余殃。有类于神道感应之说者。真可谓污蔑圣言。不识语旨矣。渐孔疏云。徐而不速谓之渐。辩说文判也。别也。谓宜别之于先也。顺与循同义。盖言顺者。仍循其道则至坚冰之意。荀爽谓臣顺君命而成之。背经旨。不可从。(文言释初六嘘吸经髓。超妙绝伦。使人惕然省。憬然悟。释上六祇以阴凝阳天玄地黄。逗露坤地生物之本。由于天地交。而总不明言。仍还经文昆仑语气。由此见圣人之言。宁使人不易知。而不能不文。太玄云。不约则其旨不详。不要则其应不博。不沈则其意不见。真能窥见载道之故者哉。)</p><h3 id="直其正也。方其义也。君子敬以直内。义以方外。敬义立而德不孤。直方大。不习无不利。则不疑其所行也。" tabindex="-1">直其正也。方其义也。君子敬以直内。义以方外。敬义立而德不孤。直方大。不习无不利。则不疑其所行也。 <a class="header-anchor" href="#直其正也。方其义也。君子敬以直内。义以方外。敬义立而德不孤。直方大。不习无不利。则不疑其所行也。" aria-label="Permalink to “直其正也。方其义也。君子敬以直内。义以方外。敬义立而德不孤。直方大。不习无不利。则不疑其所行也。”">​</a></h3><p>直则不挠。故曰直其正。言二中正也，方则不诡随。放曰方其义。言不苟同也。正直发于心。故曰直内。内直则必敬矣。故曰敬以直内。义方以接物。故曰方外。外方则无不宜矣。故曰义以方外。敬义之德立于下。五阳应于上。故德不孤。盖阴消至二遁。前承重阳。二五应予。乾先坤后。阳唱阴和。得主有利。故不疑其所行。(旧解祇惠栋知以二五相应说不孤。最为卓识。)</p><h3 id="阴虽有美。含以之以从王事。弗敢成也。地道也。妻道也。臣道也。地道无成。而代有终也。" tabindex="-1">阴虽有美。含以之以从王事。弗敢成也。地道也。妻道也。臣道也。地道无成。而代有终也。 <a class="header-anchor" href="#阴虽有美。含以之以从王事。弗敢成也。地道也。妻道也。臣道也。地道无成。而代有终也。" aria-label="Permalink to “阴虽有美。含以之以从王事。弗敢成也。地道也。妻道也。臣道也。地道无成。而代有终也。”">​</a></h3><p>阳革于午。阴代阳用事。以讫于亥。故曰代有终。凡终皆谓亥。彖传曰。乃终有庆。说卦曰万物之所成终。终皆谓亥。内经与庄子。所谓天门者此也。自复子至乾巳皆成事。阳主之。故地道无成。自姤午至坤亥皆终事。阴主之。故曰代有终。言代阳终事也。终字从冬。言一年之事。至亥冬而终也。(子即阳复)故艮居亥而艮即为终。成者法也式也。周礼天官太宰。五曰官成以经邦治。注。官成谓官府之成事品式。又秋官士师掌士之八成。注。八成犹八法。然则成者法也。地道无成者。谓坤柔不敢先创为法式。只能代阳终事也。成与终虚实先后。绝对不同。汉宋衷以成名为说。清惠栋谓成与终同义。夫成与终义诚可通。但此曰无成。曰有终。则判然二事。不得混同也。</p><h3 id="天地变化。草木蕃-天地闭。贤人隐。易曰。括囊无咎无誉。盖言谨也。" tabindex="-1">天地变化。草木蕃 天地闭。贤人隐。易曰。括囊无咎无誉。盖言谨也。 <a class="header-anchor" href="#天地变化。草木蕃-天地闭。贤人隐。易曰。括囊无咎无誉。盖言谨也。" aria-label="Permalink to “天地变化。草木蕃 天地闭。贤人隐。易曰。括囊无咎无誉。盖言谨也。”">​</a></h3><p>阴消至四八月观。由元亨而入利贞。天地之气。将变易矣。观下坤为茅茹为草。巽为木。坤闭艮止。故曰草木蕃。蕃与藩通。诗大雅四国于蕃是也。又周礼地官大司徒。九曰蕃乐。注。杜子春读蕃乐为藩乐。谓闭藏乐器而不作。贾疏。藩谓藩闭。然则草木蕃者。言草木至八月而生气藩闭也。自汉以来。无不以蕃息为解。岂知此与下天地闭贤人隐。平列为证。以释括囊之义。若作蕃息。与括囊何涉乎。乾彖传云。乾道变化。各正性命。保合太和乃利贞。言元亨时过。利贞时至也。故曰变化。此变化与彼变化同也。变化之征。在物则草木黄落。在天则阳气闭藏。在人则贤哲隐遁。谨慎也。释括囊之故也。</p><h3 id="君子黄中通理。正位居体。美在其中。而畅于四支。发于事业。美之至也。" tabindex="-1">君子黄中通理。正位居体。美在其中。而畅于四支。发于事业。美之至也。 <a class="header-anchor" href="#君子黄中通理。正位居体。美在其中。而畅于四支。发于事业。美之至也。" aria-label="Permalink to “君子黄中通理。正位居体。美在其中。而畅于四支。发于事业。美之至也。”">​</a></h3><p>地色黄。黄中色。五中位。故曰黄中。玉篇理文也。坤为文。故曰理。黄中通理者。言由中发外。有文理可见也。正位居体。即体居正位。坤为体为事业。言有黄中之德者。身必润。事业必成也。</p><h3 id="阴凝于阳必战。为其嫌于无阳也。故称龙焉。犹未离其类也。故称血焉。夫玄黄者。天地之杂也。天玄而地黄。" tabindex="-1">阴凝于阳必战。为其嫌于无阳也。故称龙焉。犹未离其类也。故称血焉。夫玄黄者。天地之杂也。天玄而地黄。 <a class="header-anchor" href="#阴凝于阳必战。为其嫌于无阳也。故称龙焉。犹未离其类也。故称血焉。夫玄黄者。天地之杂也。天玄而地黄。" aria-label="Permalink to “阴凝于阳必战。为其嫌于无阳也。故称龙焉。犹未离其类也。故称血焉。夫玄黄者。天地之杂也。天玄而地黄。”">​</a></h3><p>凝王弼本作疑。释文云。荀虞姚信蜀才作凝。兹从其多者。然疑即凝字。庄子达生篇。用志不分。乃疑于神。即凝于神也。诗大雅靡所止疑。传疑定也。正义音凝。可见疑凝本通。孟喜王弼诂作疑似之疑。致与经旨全背。夫阴阳相求相应。何疑忌之有。又何来战争。天地若至于战争。又胡由相杂。是皆由战字失诂。不知相杂者为何义也。阴凝阳即阴牝阳。阴极于亥。与伏乾相遇。坤上乾上。坤外乾内。阳不见。故曰嫌于无阳。称龙所以明有阳也。阴阳合为类。离则为独阴独阳。独阴独阳不能生。即不成为血。既曰血。即阴阳类也。即天地杂也。其血玄黄者。言此血非阴非阳。亦阴亦阳。为天地所和合。故能生万物也。旧解不知阴阳合为类。又不知此言大地生物之本。故未离其类四句。举不知其所谓。</p>',52)])])}const c=t(h,[["render",p]]);export{d as __pageData,c as default};
